/* HGSS follower Poké Ball effect (recall / release), ported to Black 2's FieldG3DObjSystem.
 * Addresses in ballfx_syms.ld (Thumb, bit 0 set); models are a/0/7/4 members from ballfx_ids.h
 * (generated by tools/follower_ballfx.py). */
#ifndef BALLFX_H
#define BALLFX_H

#include "follow.h"

#define BALLFX_RELEASE      0   /* closed ball 2 ticks, then the burst; the follower is unhidden at the burst */
#define BALLFX_RECALL       1   /* white flash + shrink (4 ticks), ball shown + follower hidden, done at tick 20 */
#define BALLFX_BURST        2   /* burst only (Surf), no visibility change */
#define BALLFX_RECALL_QUIET 3   /* recall without the flash */

/* Start an effect on the follower actor (any running one is finished first). large: size class 2
 * (64x64), which slides along its facing during the recall shrink (ballfx_offset). Positions are
 * taken from the actor now, so place it first. The effect owns the actor's hidden flag while busy. */
void ballfx_start(void *field, void *actor, u32 mode, u32 large);
/* Once per field tick (30 Hz), after the actor update. Also drops handles of a torn-down field. */
void ballfx_tick(void *field);
/* Nonzero until the effect is over (recall: tick 20, palette and scale restored). */
int ballfx_busy(void);
/* Extra draw offset (world units) to add to the actor's model offset (+0x7E / +0x80). */
void ballfx_offset(s32 *dx, s32 *dz);
/* Cancel now: free the models, restore scale, queue the palette restore. Call while the field that
 * started the effect is alive (e.g. on a zone change). Nothing is needed at field teardown: the
 * field frees its G3D objects itself and the next ballfx_tick / ballfx_start drops the handles. */
void ballfx_reset(void);

/* B2 functions (ballfx_syms.ld) */
void *Field_GetFieldEffects(void *field);
void *Field_GetG3DObjSys(void *field);
void *FieldEffects_GetArc(void *fx);
void FieldG3DObjResRequest_Clear(void *req);
void FieldG3DObjResRequest_SetModel(void *req, void *arc, u16 dat);
void FieldG3DObjResRequest_SetAnmArc(void *req, void *arc);
void FieldG3DObjResRequest_AddAnm(void *req, u16 dat);
u16 FieldG3DObjSystem_AddResGroup(void *sys, void *req, u32 preload_tex);
void FieldG3DObjSystem_FreeResGroup(void *sys, u16 grp);
u16 FieldG3DObjSystem_AddObj(void *sys, u32 grp, u16 mdl, s32 *pos);
void FieldG3DObjSystem_FreeObj(void *sys, u16 obj);
u32 FieldG3DObjSystem_StepObjAnm(void *sys, u16 obj, s32 step);   /* 0 once the last frame is reached */
void FieldG3DObjSystem_SetAnmFrame(void *sys, u16 obj, u32 anm, s32 frame);   /* anm 8 = all */
void *FldAct_GetFieldBlAct(void *actor);
u16 FldAct_GetBlActIdx(void *actor);
void *FieldBlAct_GetBlActSys(void *fblact);
void *BlActSys_GetScene(void *blsys);
void *GFL_VBlankTCBAdd(void (*fn)(void *tcb, void *data), void *data, u32 pri);
void GFL_TCBRemove(void *tcb);
int GFL_IsCardIrqEnabled(void);   /* the game's VBlank TCBs skip VRAM work while this is set */
void GX_BeginLoadTexPltt(void);
void GX_EndLoadTexPltt(void);
extern volatile u32 GX_TexPlttLcdcAddr;   /* set by GX_BeginLoadTexPltt */

#endif
